mod solution;

fn main() {
    let cases = [
    (r#"[7,3,2,9,5,11]"#, r#"true"#),
    (r#"[1,2,3]"#, r#"false"#),
    (r#"
[1,2,3]
"#, r#"false"#),
    (r#"  
[7,3,2,9,5,11]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS meet-in-middle");
}
